insert into "questions" ("paperKey", "idx", "chapter", "chapterTitle", "stem", "options", "answer", "explanation") values
('mpf', 0, '一', '第一章', '1. 計劃成員帳戶所累積的累算權益數目,取決於下列什麼條件?
i.港元利率
ii.供款款額
iii.投資回報
iv.政府津貼', '{"A":"i,ii,iii","B":"ii,iii","C":"ii","D":"iii,iv"}'::jsonb, 'A', '計劃成員帳戶所累積的累算權益數目，是完全取決於向該計劃作出的供款款額及該等供款所產生的投資回報。'),
('mpf', 1, '一', '第一章', '2. 預計到達2034年，65歲或以上人口將：', '{"A":"是現時人口兩倍","B":"會大幅減少","C":"與現時人口相約","D":"三分之一"}'::jsonb, 'D', '預計於2034年時，65歳以上人口達至34%，約佔整人口的1/3'),
('mpf', 2, '一', '第一章', '3. 據估計，在未有實施強積金之前，沒有或幾乎沒有退休保障，在香港工作人口約300萬中佔：', '{"A":"0.1","B":"三分之一","C":"一半","D":"三分之二"}'::jsonb, 'D', '在強積金實施前，估計香港大約只有三分之一的就業人口（約110萬人）受職業退休保障計劃（不論任何形式）所保障'),
('mpf', 3, '一', '第一章', '4. 強積金制度實施前，在香港約有多少比例的工作人口享有某種形式的退休保障？', '{"A":"大部份人口","B":"一半","C":"三分一","D":"小部份人口"}'::jsonb, 'C', '強積金制度實施前，大約只有三分之一的就業人口（約110萬人）受職業退休保障計劃所保障'),
('mpf', 4, '一', '第一章', '5. 在世界銀行的報告書中提倡任何老年保障計劃應包括以下三大「支柱」以作支援，「三大安老支柱」不包括：', '{"A":"由個人自發作出的儲蓄及購買的保險","B":"強制性作出的個人儲蓄及購買的保險","C":"由政府管理及由稅收資助的老人社會安全網","D":"由私營機構管理及具足額資金的強制性計劃"}'::jsonb, 'B', '世界銀行於1994年提出的三大支柱保障分案包括：1.由政府資助及管理的社會安全網；2.由私營機構管理及具備足額資金的強制性供款計劃；及3.個人自願性儲蓄'),
('mpf', 5, '一', '第一章', '6. 2005年，世界銀行就其倡議的退休保障架構增加兩根支柱，其中一根支柱為:', '{"A":"無須供款、由政府資助及管野的制度，提供最低水平的退休保障","B":"由政府管理及用稅收資助的社會安全網","C":"由私營機構管理及具足額資金的強制性供款計劃","D":"個人自願儲蓄及保險"}'::jsonb, 'A', '世界銀行於2005年提出的五大支柱包括；0支拄：無須供款、由政府資助及管理的制度，提供最低水平的退休保障，1支柱：由政府管理的強制性供款制度；2支柱：由私營機構管理及具備足額資金的強制性供款制度； 3支柱：自願性儲蓄；4支柱：非正規支援（例如家庭支援）、其他正規社會保障（例如醫療及房屋）及其他個人資產（例如自置物業）'),
('mpf', 6, '一', '第一章', '7. 預計在2064年，65歲或以上的人士將會佔香港總人口多少百分比?', '{"A":"0.36","B":"0.26","C":"0.19","D":"0.13"}'::jsonb, 'A', '預計於2064年，65歳以上的人口比例達至36%'),
('mpf', 7, '一', '第一章', '8. 預計在2064年，男性和女性在出生時的預期壽命將為多少年?', '{"A":"男性72.3年，女性78.5年","B":"男性81.2年，女性86.9年","C":"男性84.4年，女性90.8年","D":"男性87.0年，女性92.5年"}'::jsonb, 'D', '預計於2064年，男性和女性在出生時的預期壽命將分別為87歲及92.5歲'),
('mpf', 8, '一', '第一章', '9. 強制性公積金成功積金中的強是代表什麼', '{"A":"強制性參與","B":"自願性參與","C":"僱主需要參加,僱員無需參加","D":"僱員需要參加,僱主無需要參加"}'::jsonb, 'A', '強積金制度特點除包括就業為本，由私營機構管理，具備足額資金外，還有強制參與及界定供款'),
('mpf', 9, '一', '第一章', '10. 以下哪三項是強積金制度的主要特點?
i.就業為本
ii.具備足額資金
iii.由私營機構管理
iv.界定利益', '{"A":"i,ii,iii","B":"i,ii,iv","C":"i,iii,iv","D":"ii,iii,iv"}'::jsonb, 'A', '強積金制度特點除包括就業為本，由私營機構管理，具備足額資金外，還有強制參與及界定供款'),
('mpf', 10, '一', '第一章', '11. 在2044年，65歲或以上人士約佔香港總人口多少個百分比？', '{"A":"0.15","B":"0.28","C":"0.33","D":"0.36"}'::jsonb, 'C', '預計於2044年.65歳以上人口比例約佔33'),
('mpf', 11, '一', '第一章', '12. 為應對安老保障問題，世界銀行參考多個國家的退休保障制度，在1994年提出由三大支柱組成的退休保障方案，但並不包括：', '{"A":"自願性儲蓄","B":"由私營機構管理及具備足額資金的強制性供款","C":"由政府管理的社會安全網","D":"由私營機構管理自願性計劃供款制度"}'::jsonb, 'D', '世界銀行於1994年提出的三大支柱保障分案包括：1.由政府資助及管理的社會安全網；2.由私營機構管理及具備足額資金的強制性供款計劃；及3.個人自願性儲蓄'),
('mpf', 12, '一', '第一章', '13. 下列那一項不是世界銀行於1994年提出的三大「安老支柱」？', '{"A":"由政府管理及用稅收資助的社會安全網","B":"個人自願儲蓄及保險","C":"由私營機構管理及具足額資金的強制性供款計劃","D":"非正式支援、其他正式社會計劃，以及其他個人金融及非金融資產"}'::jsonb, 'D', '世界銀行於1994年提出的三大支柱保障分案包括：1.由政府資助及管理的社會安全網；2.由私營機構管理及具備足額資金的強制性供款計劃；及3.個人自願性儲蓄'),
('mpf', 13, '一', '第一章', '14. 強積金制度實施前，享有的退休保障的人,在香港約有多少比例的工作人口？', '{"A":"十分一","B":"三分一","C":"絕大部分","D":"少於一半"}'::jsonb, 'B', '在強積金實施前，估計香港大約只有三分之一的就業人口（約110萬人）受職業退休保障計劃（不論任何形式）所保障'),
('mpf', 14, '一', '第一章', '15. 社會需要設立退休保障制度，以下哪項描述是不正確的?', '{"A":"並非每個人都懂得未雨綢繆，亦未必有財政能力為退休生活作好儲備","B":"有些長者未必有子女供養他們，有些家庭則未必有財政資源為長者提供充分的照料","C":"有些長者或許要面對老年貧窮的風險","D":"有了強積金制度之後，香港政府將漸步取消長者綜合社會保障援助(綜援)"}'::jsonb, 'D', '有些長者或許要面對老年貧窮的風險。為處理此風險，社會需要設立適當的退休保障制度。'),
('mpf', 15, '二', '第二章', '1. 根據證監會的發牌制度，以下哪項人士須得到證監會發牌才可進行有關業務？', '{"A":"負責管理投資組合的投資經理","B":"負責銷售强積金的保險代理人","C":"負責銷售强積金的保險經紀","D":"以上各項皆是"}'::jsonb, 'A', '在強積金方面，證監會的主要職能是發牌給若干類別的服務提供者，包括負責管理投資組合的投資經理及從事證券借貸的保管人'),
('mpf', 16, '二', '第二章', '2. 以下哪項有關強制性公積金計劃條例的陳述是正確的
i. 所推行的計劃是由私人機構管理
ii. 所推行的計劃是與就業有關的
iii. 沒有任何其他條例與強制性公積金計劃條例有關強制性公積金計劃條例的首次立法程序於1995年開始', '{"A":"i","B":"ii, iii","C":"i, ii, iv","D":"i, ii, iii, iv"}'::jsonb, 'C', '強積金條例早於1995年制定，根據條例於1998年成立積金局，其使命包括：規管及監督私人託管的公積金計劃；教導就業人士認識退休儲蓄，並讓市民瞭解強積金制度作為退休生活保障支柱之一所發揮的作用；及推動改良公積金制度，使制度更具效率、更簡便，更能滿足就業人士的需要'),
('mpf', 17, '二', '第二章', '3. 「強制性公積金計劃條例」，為市民提供正式的退休保障邁出重要一步，這條條例是在哪一年制定的？', '{"A":"1995年","B":"1996年","C":"1998年","D":"1999年"}'::jsonb, 'A', '強制性公積金計劃條例於1995年制定，於1998年修訂條例，並制定強制性公積金計劃（一般）規例及強制性公積金計劃（豁免）規例。1999年制定強制性公積金計劃（費用）規例'),
('mpf', 18, '二', '第二章', '4. 2000年1月，職業退休計劃註冊處處長的工作，由下列哪一機構接管?', '{"A":"保險業監督","B":"金融管理專員","C":"證券及貨事務監察委員會","D":"強制性公積金計劃管理局"}'::jsonb, 'D', '2000年1月10日，積金局從職業退休計劃註冊處正式接管職業退休計劃註冊處處長的工作'),
('mpf', 19, '二', '第二章', '5. 強制性公積金計劃管理局的主要職能包括：
i.註冊公積金計劃為強積金基金
ii.確保強積金法例得以遵從
iii.補貼強積金基金的虧蝕
iv.修訂職業退休計劃條例', '{"A":"i, ii","B":"i, ii, iii","C":"i, ii, iv","D":"i, ii, iii, iv"}'::jsonb, 'A', '積金局職能包括：確保強積金法例獲得遵守；為強積金計劃計劃註冊；核准符合資格的人擔任核准受託人；規管核准受託人的事務及活動；對與強積金計劃有關的銷售及推銷活動及強積金計劃有關的意見，作出規管；監督核准受託人的強積金計劃行政及管理工作；就強制性供款的支付訂立規則或指引，並就強積金計劃在該等供款方面的管理訂立規則或指引；提出與職業退休計劃或公積金計劃有關的法律改革及促進本港退休計劃行業的發展'),
('mpf', 20, '二', '第二章', '6. 為強積金計劃註冊，批核強積金投資基金及核准匯集投資基金是以下哪個機構的主要職能？', '{"A":"保險業監督","B":"強制性公積金計劃管理局","C":"證券及期貨事務監察委員會","D":"金融管理專員"}'::jsonb, 'B', '積金局職能包括：確保強積金法例獲得遵守；為強積金計劃計劃註冊；核准符合資格的人擔任核准受託人；規管核准受託人的事務及活動；對與強積金計劃有關的銷售及推銷活動及強積金計劃有關的意見，作出規管；監督核准受託人的強積金計劃行政及管理工作；就強制性供款的支付訂立規則或指引，並就強積金計劃在該等供款方面的管理訂立規則或指引；提出與職業退休計劃或公積金計劃有關的法律改革及促進本港退休計劃行業的'),
('mpf', 21, '二', '第二章', '7. 強積金制度中牽涉：', '{"A":"銀行業","B":"銀行及保險業","C":"銀行及保險及證券業","D":"以上各項都不包括"}'::jsonb, 'C', '除了積金局外，證券及期貨事務監察委員會、保險業監管局及金融管理專員亦在規管強積金產品、服務提供者及註冊中介人方面擔當重要的角色'),
('mpf', 22, '二', '第二章', '8. 以下哪項或多項金融機構屬於強積金的規管組織？', '{"A":"證券及期貨事務監察委員會","B":"保險業監督","C":"金融管理專員","D":"以上各項皆是"}'::jsonb, 'D', '除了積金局外，證券及期貨事務監察委員會、保險業監管局及金融管理專員亦在規管強積金產品、服務提供者及註冊中介人方面擔當重要的角色'),
('mpf', 23, '二', '第二章', '9. 證券及期貨事務監察委員會是強積金制度下的其中一個規管機構，以下哪項不是它的職能？', '{"A":"保障投資者的權益","B":"發牌於某些強積金服務提供者","C":"規管其轄下的強積金中介人","D":"開設保險單類別之匯集投資基金"}'::jsonb, 'D', '保險單由保險保監局負責監管'),
('mpf', 24, '二', '第二章', '10. 根據證監會的發牌制度，以下哪項人士須得到證監會發牌才可進行有關業務？', '{"A":"負責管理投資組合的投資經理","B":"負責銷售強積金的保險代理人","C":"負責銷售強積金的保險經紀","D":"以上各項皆是"}'::jsonb, 'A', '證監會負責發牌給：負責管理投資組合的投資經理及從事證券借貸的保管人'),
('mpf', 25, '二', '第二章', '11. 在強積金制度下，證監會的職能包括：', '{"A":"核准受託人","B":"規管轄下的保險中介人","C":"規管轄下的強積金中介人","D":"以上所有選擇"}'::jsonb, 'C', '證監會的職能包括：批核／認可與強積金產品有關的要約文件及市場推廣資料，認可強積金計劃（包括其成分基金）及匯集投資基金；發牌給負責管理投資'),
('mpf', 26, '二', '第二章', '12. 哪一機構是負責審查資料披露事宜，批核投資經理及審核銷售文件及宣傳資料?', '{"A":"香港金融管理局","B":"強制性公積金計劃管理局","C":"證監會","D":"香港保險業聯會"}'::jsonb, 'C', '證監會的職能包括：批核／認可與強積金產品有關的要約文件及市場推廣資料，認可強積金計劃（包括其成分基金）及匯集投資基金；發牌給負責管理投資組合的投資經理及從事證券借貸的保管人及負責監督和調查以證券為主要業務的有關註冊強積金中介人'),
('mpf', 27, '二', '第二章', '13. 證券及期貨事務監察委員會須發牌予進行強積金業務人士，包括：', '{"A":"經營證券借貸人士","B":"銷售強積金的保險代理人","C":"銷售強積金的保險經紀","D":"以上各項皆是"}'::jsonb, 'A', '證監會的職能包括：批核／認可與強積金產品有關的要約文件及市場推廣資料，認可強積金計劃（包括其成分基金）及匯集投資基金；發牌給負責管理投資組合的投資經理及從事證券借貸的保管人及負責監督和調查以證券為主要業務的有關註冊強積金中介人'),
('mpf', 28, '二', '第二章', '14. 證券及期貨事務監察委員會在強積金方面的角色是：', '{"A":"規管獲其發牌或註冊的強積金中介人","B":"發牌給從事證券借貸的投資經理及保管人","C":"批核認可要約文件及市場推廣資料","D":"以上各項皆是"}'::jsonb, 'D', '證監會的職能包括：批核／認可與強積金產品有關的要約文件及市場推廣資料，認可強積金計劃（包括其成分基金）及匯集投資基金；發牌給負責管理投資組合的投資經理及從事證券借貸的保管人及負責監督和調查以證券為主要業務的有關註冊強積金中介人'),
('mpf', 29, '二', '第二章', '15. 負責確保保險公司不單持有足夠資產償還債務，並且符合資本及償付能力規定的金融規管機構為：', '{"A":"保險業監督","B":"香港金融管理局","C":"香港保險業聯會","D":"證監會"}'::jsonb, 'A', '保監局的主要職能是確保從事強積金服務的保險公司妥善運作，並有足夠資產償還債務，以符合保險業條例的規定及獲積金局認可的要約文件等同獲證監會認可的銷售文件；負責監督和調查以保險為主要業務的有關註冊強積金中介人'),
('mpf', 30, '二', '第二章', '16. 保險業監督的職能包括：', '{"A":"確保保險公司妥善運作","B":"確保保險公司有足夠資產履行責任","C":"監管在保險業監管體系下的強積金中介人","D":"以上所列各項"}'::jsonb, 'D', '保監局的主要職能是確保從事強積金服務的保險公司妥善運作，並有足夠資產償還債務，以符合保險業條例的規定及獲積金局認可的要約文件等同獲證監會認可的銷售文件；負責監督和調查以保險為主要業務的有關註冊強積金中介人'),
('mpf', 31, '二', '第二章', '17. 哪一個機構負責規管認可銀行的運作？', '{"A":"強積金計劃管理局(管理局)","B":"保險業監理處(保監處)","C":"證券及期貨事務監察委員會(證監會)","D":"香港金融管理局(金管局)"}'::jsonb, 'D', '金管局負責規管在香港參與強積金制度的認可機構（包括銀行），不論其身分是保管人、強積金投資產品擔保人，還是向受託人或保管人持續提供財政支援的機構；金融管理專員亦負責確保該等機構財政健全及負責監督和調查以銀行為主要業務的有關註冊強積金中介人'),
('mpf', 32, '二', '第二章', '18. 金融管理專員規管銀行及確保銀行', '{"A":"必須有利潤","B":"財政健全","C":"不與保險公司競爭","D":"以上各項皆是"}'::jsonb, 'B', '金管局負責規管在香港參與強積金制度的認可機構（包括銀行），不論其身分是保管人、強積金投資產品擔保人，還是向受託人或保管人持續提供財政支援的機構；金融管理專員亦負責確保該等機構財政健全及負責監督和調查以銀行為主要業務的有關註冊強積金中介人'),
('mpf', 33, '二', '第二章', '19. 除了證監會及保監處，以下哪一個機構也是為強積金制度作出金融規管？', '{"A":"香港保險顧問聯會","B":"香港專業保險經紀協會","C":"香港金融管理局","D":"香港保險業聯會"}'::jsonb, 'C', '除了積金局,證券及期貨事務監察委員會外，保險業監督及金融管理專員亦在規管強積金產品、服務提供者及註冊中介人方面擔當重要的角色'),
('mpf', 34, '二', '第二章', '20. 規管在香港參予強積金制度的銀行，以及確保銀行財政健全的規管機構稱為：', '{"A":"存款公司公會","B":"香港銀行公會","C":"金融管理專員","D":"證券及期貨事務監察委員會"}'::jsonb, 'C', '金管局負責規管在香港參與強積金制度的認可機構（包括銀行），不論其身分是保管人、強積金投資產品擔保人，還是向受託人或保管人持續提供財政支援的機構；金融管理專員亦負責確保該等機構財政健全及負責監督和調查以銀行為主要業務的有關註冊強積金中介人'),
('mpf', 35, '二', '第二章', '21. 強積金條例，與附屬的強積金規例，統稱：', '{"A":"強積金法例","B":"強積金指引","C":"強積金條款","D":"相關的監管機構"}'::jsonb, 'A', '強積金法例包括《強積金條例》及三套主要附屬法例，分別為《強制性公積金計劃（一般）規例》及《強制性公積金計劃（豁免）規例》，以及《強制性公積金計劃（費用）規例》'),
('mpf', 36, '二', '第二章', '22. 強制性公積金計劃(一般)規例，規定以下哪些事宜：
